    valid_wav_path = segments_dir / '0001_0001.wav'
    valid_wav_path.write_bytes(wav_bytes)
    
    encoded = base64.b64encode(wav_bytes).decode('ascii')
    mock_response = MagicMock()
    mock_response.read.return_value = json.dumps({
        "status": "completed",
        "steps": [{"type": "model_output", "content": [{"type": "audio", "data": encoded, "mime_type": "audio/wav"}]}],
        "usage_metadata": {"prompt_token_count": 10, "candidates_token_count": 20}
    }).encode('utf-8')
    mock_opener.return_value.open.return_value.__enter__.return_value = mock_response
    
    with patch('bookcast.adapters.gemini.request.Request') as mock_req:
        with open('generate_gemini_final_5min.py') as f:
            code = f.read()
            
        code = code.replace("base_dir = Path('output/llm-cost-clean-5min-v5/b288c0f91d3e46f32eb95916')", f"base_dir = Path('{base_dir}')")
        code = code.replace("out_dir = Path('output/gemini-final-5min')", f"out_dir = Path('{out_dir_path}')")
        
        namespace = {'__name__': '__main__'}
        exec(code, namespace)
        
        # It should only call API for 0002.json, because 0001.json is checkpointed!
        assert mock_req.call_count == 1
        
        payload = json.loads(mock_req.call_args[1]['data'])
        assert payload['generation_config']['speech_config']['speakers'][0]['voice'] == "Kore"
        assert payload['generation_config']['speech_config']['speakers'][1]['voice'] == "Puck"
        assert "Natural Mandarin Chinese podcast guest" in payload['input'][0]['content'][0]['annotations'][0]['style']
        assert payload['input'][0]['content'][0]['text'] == "继续"
        
        podcast_wav = out_dir_path / 'podcast.wav'
        assert podcast_wav.exists()
        with wave.open(str(podcast_wav), 'rb') as w:
            assert w.getnframes() > 0
            
        meta_file = out_dir_path / 'metadata.json'
        assert meta_file.exists()
        meta = json.loads(meta_file.read_text())
        assert meta['script_turn_count'] == 4
        assert meta['synthesized_turn_count'] == 4
        assert meta['request_count'] == 1
        assert meta['retry_count'] == 0
        assert meta['gemini_usage_metadata']['input_tokens'] == 10
